"use strict";

// The vulnerable sink the advisory names. Every module in this fixture
// that reaches it does so during MODULE EVALUATION -- there is no
// conditional export, no branch and no entrypoint call involved, which is
// the whole point of RWF-023: the defect it fixes is about which code the
// analyzer believes runs at load time, not about which export write wins.
function explode(input) {
  return "danger:" + input;
}

exports.explode = explode;
